-- 3. Rooms: add missing ones, fix floors of existing ones.
with v(name_th, floor) as (values ('RB1101', 1), ('RB1102', 1)), bld as (select id from buildings where name_th = 'RB1 อาคารเรียนรวม 1 (ทรงกลม)' order by id limit 1)
, upd as (update rooms r set floor = v.floor from v, bld where r.building_id = bld.id and r.name_th = v.name_th and r.floor <> v.floor returning r.id)
